// Package testimage generates deterministic image carriers for scanner tests.
package testimage

import (
	"bytes"
	"crypto/sha256"
	"encoding/base64"
	"encoding/binary"
	"encoding/json"
	"fmt"
	"hash/crc32"
	"image"
	"image/color/palette"
	"image/gif"
	"image/jpeg"
	"image/png"
	"regexp"
	"strconv"
	"testing"
)

// Payload returns a complete image of 1.5-3.5 MiB whose base64 spelling has an
// AWS credential-shaped run, generated by searching deterministic noise seeds.
// The decoded bytes do not intentionally contain a credential.
func Payload(t testing.TB, format string) []byte {
	t.Helper()
	shape := regexp.MustCompile(`(?i)(AKIA|ASIA)[A-Z0-9]{16}`)
	for seed := uint64(0); seed < 64; seed++ {
		var out bytes.Buffer
		var err error
		switch format {
		case "png", "jpeg":
			size := 800
			if format == "jpeg" {
				size = 1280
			}
			img := image.NewRGBA(image.Rect(0, 0, size, size))
			fillImageNoise(img.Pix, seed)
			for i := 3; i < len(img.Pix); i += 4 {
				img.Pix[i] = 255
			}
			if format == "png" {
				err = png.Encode(&out, img)
			} else {
				err = jpeg.Encode(&out, img, &jpeg.Options{Quality: 100})
			}
		case "gif":
			img := image.NewPaletted(image.Rect(0, 0, 1152, 1152), palette.Plan9)
			fillImageNoise(img.Pix, seed)
			err = gif.Encode(&out, img, nil)
		case "webp":
			// Complete 2x2 VP8 keyframe, followed by a RIFF unknown chunk. WebP
			// readers must ignore unknown chunks (RIFF container specification).
			out.Write([]byte{
				'R', 'I', 'F', 'F', 0, 0, 0, 0, 'W', 'E', 'B', 'P', 'V', 'P', '8', ' ', 24, 0, 0, 0,
				0x30, 1, 0, 0x9d, 1, 0x2a, 2, 0, 2, 0, 2, 0, 0x34, 0x25, 0xa4, 0, 3, 0x70, 0, 0xfe, 0xfb, 0x94, 0, 0,
			})
			noise := make([]byte, 2<<20)
			fillImageNoise(noise, seed)
			out.WriteString("JUNK")
			if err = binary.Write(&out, binary.LittleEndian, fixtureSize(t, len(noise))); err == nil {
				out.Write(noise)
			}
			binary.LittleEndian.PutUint32(out.Bytes()[4:8], fixtureSize(t, out.Len()-8))
		default:
			t.Fatalf("unsupported fixture format %s", format)
		}
		if err != nil {
			t.Fatal(err)
		}
		payload := out.Bytes()
		if len(payload) < 3*(1<<19) || len(payload) > 7*(1<<19) {
			t.Fatalf("fixture size %d outside 1.5-3.5 MiB", len(payload))
		}
		if shape.MatchString(base64.StdEncoding.EncodeToString(payload)) {
			return payload
		}
	}
	t.Fatal("no credential-shaped image found in seed search")
	return nil
}

// Carrier returns an Anthropic image source, MCP image block or OpenAI Images
// b64_json result. OpenAI's result has no media declaration; validation must
// derive its type from the complete decoded image.
func Carrier(t testing.TB, shape, format string, payload []byte) string {
	t.Helper()
	data := base64.StdEncoding.EncodeToString(payload)
	var value any
	switch shape {
	case "anthropic":
		value = map[string]any{"type": "image", "source": map[string]string{"type": "base64", "media_type": "image/" + format, "data": data}}
	case "mcp":
		value = map[string]string{"type": "image", "mimeType": "image/" + format, "data": data}
	case "openai":
		value = map[string]any{"data": []any{map[string]string{"b64_json": data}}}
	default:
		t.Fatalf("unsupported carrier %s", shape)
	}
	raw, err := json.Marshal(value)
	if err != nil {
		t.Fatal(err)
	}
	return string(raw)
}

// SmallPNG returns a renderer-readable PNG with either a literal secret in a
// text chunk, or binary bytes whose base64 spelling contains a key-shaped run.
func SmallPNG(t testing.TB, literal string) []byte {
	t.Helper()
	var out bytes.Buffer
	if err := png.Encode(&out, image.NewRGBA(image.Rect(0, 0, 1, 1))); err != nil {
		t.Fatal(err)
	}
	body := []byte("Comment\x00" + literal)
	if literal == "" {
		decoded, err := base64.StdEncoding.DecodeString("akia" + "AAAAAAAAAAAAAAAA")
		if err != nil {
			t.Fatal(err)
		}
		body = append([]byte("Comment\x00xx"), decoded...)
	}
	var chunk bytes.Buffer
	if err := binary.Write(&chunk, binary.BigEndian, fixtureSize(t, len(body))); err != nil {
		t.Fatal(err)
	}
	chunk.WriteString("tEXt")
	chunk.Write(body)
	if err := binary.Write(&chunk, binary.BigEndian, crc32.ChecksumIEEE(chunk.Bytes()[4:])); err != nil {
		t.Fatal(err)
	}
	pngBytes := out.Bytes()
	result := append([]byte(nil), pngBytes[:33]...)
	result = append(result, chunk.Bytes()...)
	return append(result, pngBytes[33:]...)
}

func fixtureSize(t testing.TB, n int) uint32 {
	t.Helper()
	var value uint32
	if _, err := fmt.Sscan(strconv.Itoa(n), &value); err != nil {
		t.Fatalf("fixture size: %v", err)
	}
	return value
}

// fillImageNoise expands a deterministic seed into synthetic image noise.
func fillImageNoise(dst []byte, seed uint64) {
	var input [16]byte
	binary.LittleEndian.PutUint64(input[:8], seed)
	for counter := uint64(0); len(dst) > 0; counter++ {
		binary.LittleEndian.PutUint64(input[8:], counter)
		block := sha256.Sum256(input[:])
		dst = dst[copy(dst, block[:]):]
	}
}
